function contohLevel1(n) {
  var hasil = 0;
  var i = 0;
  while (i < n) {
    hasil = hasil + i;
    i = i + 1;
  }
  return hasil;
}

var hasil = contohLevel1(5);

function contohLevel2(batas) {
  var nilai = 0;
  var hasil = [];
  while (nilai < batas) {
    nilai = nilai + 3;
    hasil.push(nilai);
  }
  return hasil;
}

var hasil = contohLevel2(10);
